SELECT p.id, 'Alianza de usuarios', 'integrantes-alianza-de-usuarios', 'Integrantes de la Alianza de Usuarios de la E.S.E. Hospital San José del Guaviare y su funcionamiento.', '<h3>Integrantes</h3>
<ul>
